CREATE INDEX idx_events_type_date ON service_events(event_type,date_hint);
CREATE INDEX idx_events_actor ON service_events(actor_text);
CREATE INDEX idx_events_subject ON service_events(subject_text);
CREATE INDEX idx_events_message_id ON service_events(telegram_message_id);
CREATE TABLE messages_index (telegram_message_id INTEGER PRIMARY KEY,date_unix INTEGER,sender_id TEXT);
CREATE TABLE sender_names (sender_id TEXT PRIMARY KEY,sender_name TEXT);
CREATE TABLE message_context_candidates (telegram_message_id INTEGER PRIMARY KEY,date_local TEXT,sender_id TEXT,sender_name TEXT,message_text TEXT);
